$stats=['competitors'=>(int)$pdo->query('SELECT COUNT(*) FROM bdc_competitors')->fetchColumn(),'events'=>(int)$pdo->query('SELECT COUNT(*) FROM bdc_events')->fetchColumn(),'points'=>(int)$pdo->query('SELECT COUNT(*) FROM bdc_point_transactions')->fetchColumn(),'claims'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_claims WHERE status='pending'")->fetchColumn(),'profile_requests'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_profile_requests WHERE status IN ('pending','under_review','more_info')")->fetchColumn()];$stats['identity_matches']=(int)$pdo->query("SELECT COUNT(*) FROM bdc_competitor_link_suggestions WHERE status='pending'")->fetchColumn();$stats['completed_events']=(int)$pdo->query("SELECT COUNT(*) FROM bdc_events e LEFT JOIN bdc_scoring_archived_events a ON a.event_id=e.id WHERE e.status='completed' AND a.event_id IS NULL")->fetchColumn();$recentImports=$pdo->query('SELECT id,file_name,import_type,status,total_rows,imported_rows,error_rows,created_at FROM bdc_import_batches ORDER BY id DESC LIMIT 5')->fetchAll();$recentEvents=$pdo->query("SELECT id,name,event_date,status FROM bdc_events ORDER BY COALESCE(event_date,'1900-01-01') DESC,id DESC LIMIT 5")->fetchAll();$recentRegistrations=$pdo->query("SELECT r.id,r.full_name,r.created_at,r.registration_status,e.name AS event_name FROM bdc_event_registrations r JOIN bdc_events e ON e.id=r.event_id ORDER BY r.id DESC LIMIT 5")->fetchAll();$stats['registrations']=(int)$pdo->query('SELECT COUNT(*) FROM bdc_event_registrations')->fetchColumn();$stats['documents']=(int)$pdo->query("SELECT COUNT(*) FROM bdc_result_documents WHERE status='published'")->fetchColumn();$pendingCompetitionApprovals=$pdo->query("SELECT p.final_round_id,p.division,p.submitted_at,e.name event_name,e.event_date FROM bdc_scoring_publications p JOIN bdc_events e ON e.id=p.event_id WHERE p.status='pending_approval' ORDER BY p.submitted_at")->fetchAll();$pendingPointAdjustments=[];try{$pendingPointAdjustments=$pdo->query("SELECT r.id,r.additional_points,r.requested_at,c.exact_name,e.name event_name,r.division,r.dance_role,u.full_name requester_name FROM bdc_point_adjustment_requests r JOIN bdc_competitors c ON c.id=r.competitor_id JOIN bdc_events e ON e.id=r.event_id JOIN bdc_users u ON u.id=r.requested_by WHERE r.status='pending' ORDER BY r.requested_at")->fetchAll();}catch(Throwable $e){}
$activeArchiveEvents=[];try{$activeArchiveEvents=$pdo->query("SELECT e.id,e.name,e.event_date,e.status,COUNT(r.id) scoring_rounds FROM bdc_events e LEFT JOIN bdc_scoring_rounds r ON r.event_id=e.id LEFT JOIN bdc_scoring_archived_events a ON a.event_id=e.id WHERE a.event_id IS NULL AND e.status='completed' GROUP BY e.id,e.name,e.event_date,e.status ORDER BY COALESCE(e.event_date,'9999-12-31') DESC,e.id DESC")->fetchAll();}catch(Throwable $e){}
